import { Job, OCRResult, SmartToolLayer } from '@/types'

/**
 * Two ways to run the v2 demo:
 *  - with the demo server (server/): requests go to NEXT_PUBLIC_API_URL
 *  - as a static site (GitHub Pages, NEXT_PUBLIC_STATIC_DEMO=1): there is no server.
 *    GET requests read files generated by tools/export_static_api.py under
 *    <basePath>/demo-api, and the few write requests the UI makes are answered
 *    here in the browser. Nothing is stored in either mode.
 */
export const STATIC_DEMO = process.env.NEXT_PUBLIC_STATIC_DEMO === '1'
const API_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5015'
export const API_BASE_URL = API_URL

/** v1 (the original compare demo), published next to v2 on GitHub Pages */
export const V1_URL = STATIC_DEMO
  ? `${process.env.NEXT_PUBLIC_BASE_PATH || ''}/v1/`
  : 'https://dnss1.github.io/searchable-pdf-generator/v1/'

const READ_ONLY_DETAIL = '데모 버전은 체험 전용입니다. 파일 업로드, 세션 생성·수정·삭제, OCR 실행은 지원하지 않습니다.'

// Endpoints served as files. Everything else under /api is JSON, stored as "<path>.json".
const FILE_PATHS = [
  /^\/api\/files\//,
  /^\/files\//,
  /^\/api\/download-json\//,
  /^\/api\/export\/[^/]+\/(txt|xml|excel|all)$/,
  /^\/api\/demo\/samples\/[^/]+\/input(\.\w+)?$/,
  /^\/api\/sessions\/export-download\//,
]

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), { status, headers: { 'Content-Type': 'application/json' } })
}

function staticUrl(path: string): string {
  return `${API_URL}${FILE_PATHS.some((re) => re.test(path)) ? path : `${path}.json`}`
}

async function staticGet(path: string, params: URLSearchParams): Promise<Response> {
  const res = await fetch(staticUrl(path))
  if (!res.ok || path !== '/api/jobs') return res
  // The jobs page filters on the server; do the same here
  const status = params.get('status')
  const search = (params.get('search') || '').toLowerCase()
  const jobs: Array<{ status: string; filename?: string }> = await res.json()
  return json(jobs.filter((j) => (!status || j.status === status) && (!search || (j.filename || '').toLowerCase().includes(search))))
}

function staticWrite(method: string, path: string): Promise<Response> | Response {
  let m: RegExpMatchArray | null
  if (method === 'POST' && (m = path.match(/^\/api\/save-edits\/([^/]+)$/))) {
    return json({ status: 'success', message: '데모 버전: 수정 내용은 이 브라우저에서만 유지되고 저장되지 않습니다.', saved_at: new Date().toISOString() })
  }
  if (method === 'POST' && (m = path.match(/^\/api\/export\/([^/]+)$/))) {
    return json({
      message: 'Export completed',
      pdf_url: `/api/files/processed/${m[1]}.pdf`,
      json_url: `/api/download-json/${m[1]}`,
      demo_notice: '데모 버전에서는 편집 내용이 저장되거나 PDF에 반영되지 않습니다. 처리 결과 PDF를 그대로 내려받습니다.',
    })
  }
  // Exports built in advance for every format (the demo returns them for any selection)
  if (method === 'POST' && /^\/api\/export\/[^/]+\/multi$/.test(path)) return fetch(`${API_URL}${path}.zip`)
  if (method === 'POST' && /^\/api\/sessions\/[^/]+\/export-(merged|multi)$/.test(path)) return fetch(`${API_URL}${path}.json`)
  if (method === 'PATCH' && /^\/api\/sessions\/[^/]+\/selection$/.test(path)) return json({ status: 'success' })
  return json({ detail: READ_ONLY_DETAIL }, 403)
}

/** fetch() for API calls; same arguments and result as fetch */
export async function apiFetch(input: string, init?: RequestInit): Promise<Response> {
  if (!STATIC_DEMO) return fetch(input, init)
  const url = new URL(input, window.location.origin)
  const path = url.pathname.startsWith(API_URL) ? url.pathname.slice(API_URL.length) : url.pathname
  const method = (init?.method || 'GET').toUpperCase()
  return method === 'GET' ? staticGet(path, url.searchParams) : staticWrite(method, path)
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await apiFetch(`${API_URL}/api${path}`, {
    ...init,
    headers: { 'Content-Type': 'application/json', ...init?.headers },
  })
  if (!res.ok) {
    const body = await res.json().catch(() => null)
    throw new Error(body?.detail || `Request failed (${res.status})`)
  }
  return res.json()
}

export const getJobStatus = (jobId: string): Promise<Job> => request(`/status/${jobId}`)

export const getOCRResults = (jobId: string): Promise<OCRResult> => request(`/ocr-results/${jobId}`)

export const getProcessedFileUrl = (jobId: string): string => {
  // No timestamp here - let the component handle cache busting if needed
  return `${API_URL}/api/files/processed/${jobId}.pdf`
}

export const getJSONDownloadUrl = (jobId: string): string => {
  return `${API_URL}/api/download-json/${jobId}`
}

export interface ExportPayload {
  ocr_results: OCRResult
  smart_layers: SmartToolLayer[]
}

export interface ExportResponse {
  pdf_url: string
  json_url?: string
  smart_layers_url?: string
  demo_notice?: string
}

export const exportDocument = (jobId: string, payload: ExportPayload): Promise<ExportResponse> =>
  request(`/export/${jobId}`, { method: 'POST', body: JSON.stringify(payload) })

// Auto-save OCR edits
export interface SaveEditsPayload {
  edits: Array<{
    page_number: number
    line_index: number
    original_text: string
    new_text: string
  }>
  ocr_results?: OCRResult
}

export interface SaveEditsResponse {
  status: string
  message: string
  saved_at: string
}

export const saveOCREdits = (jobId: string, payload: SaveEditsPayload): Promise<SaveEditsResponse> =>
  request(`/save-edits/${jobId}`, { method: 'POST', body: JSON.stringify(payload) })
